// Makes server/browser/readability/source.ts from Mozilla's Readability.js beside it (Apache-2.0, kept unchanged with its
// LICENSE.md), so the server's bundle carries the library as a string it can run inside a page. Run it again when
// Readability.js is replaced by a newer version: node scripts/readability-source.mjs
import fs from 'node:fs';

const dir = new URL('../server/browser/readability/', import.meta.url);
const src = fs.readFileSync(new URL('Readability.js', dir), 'utf8');
const out = [
  '// Generated by scripts/readability-source.mjs from Readability.js beside it: Mozilla Readability, Copyright (c) 2010 Arc90 Inc,',
  '// Apache License 2.0 (LICENSE.md beside it). Do not edit; replace Readability.js and run the script again.',
  `export const READABILITY_SRC = ${JSON.stringify(src)};`,
  '',
].join('\n');
fs.writeFileSync(new URL('source.ts', dir), out);
console.log(`server/browser/readability/source.ts: ${src.length} characters of Readability.js`);
